unsafe fn BitStream_writeBytes(
    mut dest: *mut c_uchar,
    mut size: size_t,
    mut data: *mut c_uchar,
) {
    let data_view: &[c_uchar] = unsafe { core::slice::from_raw_parts(data, (size) as usize) };
    let mut mask: c_uchar = 0;
    let mut i: size_t = 0;
    let mut j: size_t = 0;
    let mut p: *mut c_uchar = ::core::ptr::null_mut::<c_uchar>();
    p = dest;
    i = 0 as size_t;
    while i < size {
        mask = 0x80 as c_uchar;
        j = 0 as size_t;
        while j < 8 as size_t {
            if data_view[(i) as usize] as c_int & mask as c_int != 0 {
                *p = 1 as c_uchar;
            } else {
                *p = 0 as c_uchar;
            }
            p = p.offset(1);
            mask = (mask as c_int >> 1 as c_int) as c_uchar;
            j = j.wrapping_add(1);
        }
        i = i.wrapping_add(1);
    }
}
